void fill(int[][] g,int r,int c,int from,int to){
  if(r<0||c<0||r>=g.length||c>=g[0].length||g[r][c]!=from) return;
  g[r][c]=to;
  fill(g,r+1,c,from,to); fill(g,r-1,c,from,to);
  fill(g,r,c+1,from,to); fill(g,r,c-1,from,to);
}

