def fill(g, r, c, src, tgt):
    if r<0 or c<0 or r>=len(g) or c>=len(g[0]) or g[r][c]!=src: return
    g[r][c] = tgt
    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
        fill(g, r+dr, c+dc, src, tgt)
